if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/goliath-appointment-queue.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function sbq($ep){$ch=curl_init(rtrim(SUPABASE_URL,'/').'/rest/v1/'.ltrim($ep,'/'));curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_HTTPHEADER=>['apikey: '.SUPABASE_SERVICE_ROLE_KEY,'Authorization: Bearer '.SUPABASE_SERVICE_ROLE_KEY,'Content-Type: application/json'],CURLOPT_TIMEOUT=>25]);$b=curl_exec($ch);$http=curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);$d=json_decode($b,true);return ($http>=200&&$http<300&&is_array($d))?$d:[];}
$q=sbq('goliath_outreach_queue?select=*&order=created_at.desc&limit=100');
?><!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jessica Appointment Queue</title><link rel="stylesheet" href="/dashboard/assets/goliath-v33.css?v=459"><link rel="stylesheet" href="/dashboard/assets/goliath-v45-final.css?v=459"><style>.msg{white-space:pre-wrap;background:#07101f;border:1px solid rgba(255,255,255,.12);border-radius:14px;padding:12px;margin-top:8px}.status{border-radius:20px;background:#1d2a44;padding:4px 8px;font-size:12px}</style></head><body><div class="shell"><?php require __DIR__.'/includes/goliath-sidebar-v33.php'; ?><main class="main"><section class="top"><div><h1>✉️ Jessica Appointment Queue</h1><p>Review-ready appointment emails. Human approval keeps the outreach personal, compliant and on-brand.</p></div><div class="brandbar"><a class="btn dark" href="/dashboard/goliath-scout-intelligence.php">Scout Leads</a><a class="btn dark" href="/dashboard/goliath-mission-control.php">Mission Control</a></div></section><section class="panel"><h2>Outbound Appointment Requests <span><?=count($q)?> items</span></h2><div class="inner"><?php if(!$q):?><p>No appointment emails queued yet.</p><?php endif;?><?php foreach($q as $m):?><div class="event"><div><strong><?=h($m['subject']??'Appointment request')?></strong><br><small>To: <?=h($m['contact_name']??'')?> <?=h($m['contact_email']??'')?> <?=h($m['contact_phone']??'')?></small><br><span class="status"><?=h($m['status']??'review_required')?></span><div class="msg"><?=h($m['body']??'')?></div></div></div><?php endforeach;?></div></section></main></div></body></html>
